using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Relay.Infrastructure.Composition;

namespace Relay.Api.Tests.Fixtures;

public sealed class RelayApiFactory(
    string? connectionString,
    string environmentName,
    Action<IServiceCollection>? overrideServices = null) : WebApplicationFactory<Program>
{
    public const string ConnectionStringSetting = $"ConnectionStrings:{InfrastructureServiceCollectionExtensions.ConnectionStringName}";

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.UseEnvironment(environmentName);
        builder.ConfigureAppConfiguration(configuration =>
            configuration.AddInMemoryCollection([new KeyValuePair<string, string?>(ConnectionStringSetting, connectionString)]));
        if (overrideServices is not null)
        {
            builder.ConfigureTestServices(overrideServices);
        }
    }
}
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Relay.Api.Tests.Fixtures;
using Relay.Infrastructure.Composition;

namespace Relay.Api.Tests.Startup;

[Collection(SeededApiTestGroup.Name)]
public sealed class ConnectionStringTests(SeededApiFixture fixture) : SeededApiTest(fixture)
{
    [Fact]
    public void StartTestHostUsesTheContainerConnectionStringOverAnyShellValue()
    {
        var configuration = Fixture.Factory.Services.GetRequiredService<IConfiguration>();

        configuration.GetConnectionString(InfrastructureServiceCollectionExtensions.ConnectionStringName)
            .ShouldBe(Fixture.SeededConnectionString);
    }

    [Fact]
    public async Task StartInDevelopmentWithoutConnectionStringFailsFastNamingTheSetting()
    {
        await using var factory = new RelayApiFactory(connectionString: null, Environments.Development);

        var startupFailure = Should.Throw<Exception>(() => factory.CreateClient().Dispose());

        MessagesOf(startupFailure).ShouldContain(
            message => message.Contains("ConnectionStrings:Relay", StringComparison.Ordinal)
                || message.Contains("ConnectionStrings__Relay", StringComparison.Ordinal));
    }

    private static List<string> MessagesOf(Exception startupFailure)
    {
        var messages = new List<string>();
        var pending = new Stack<Exception>([startupFailure]);
        while (pending.TryPop(out var exception))
        {
            messages.Add(exception.Message);
            if (exception is AggregateException aggregate)
            {
                aggregate.InnerExceptions.ToList().ForEach(pending.Push);
            }
            else if (exception.InnerException is not null)
            {
                pending.Push(exception.InnerException);
            }
        }

        return messages;
    }
}
using Microsoft.EntityFrameworkCore;
using Relay.Infrastructure.Composition;
using Relay.Infrastructure.Persistence;

namespace Relay.Api.Composition;

public sealed partial class DevelopmentDatabaseMigrator(
    IConfiguration configuration,
    IServiceScopeFactory serviceScopeFactory,
    ILogger<DevelopmentDatabaseMigrator> logger) : IHostedService
{
    private const string ConnectionStringSetting = $"ConnectionStrings:{InfrastructureServiceCollectionExtensions.ConnectionStringName}";
    private const string ConnectionStringEnvironmentVariable = $"ConnectionStrings__{InfrastructureServiceCollectionExtensions.ConnectionStringName}";

    // The ~2.4 MB seed runs as one migration and can exceed EF's default 30 s command timeout.
    private static readonly TimeSpan MigrationCommandTimeout = TimeSpan.FromMinutes(10);

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        EnsureConnectionStringIsSet();

        await using var scope = serviceScopeFactory.CreateAsyncScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<RelayDbContext>();
        dbContext.Database.SetCommandTimeout(MigrationCommandTimeout);

        LogApplyingMigrations(logger);
        await dbContext.Database.MigrateAsync(cancellationToken);
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    private void EnsureConnectionStringIsSet()
    {
        if (!string.IsNullOrWhiteSpace(configuration.GetConnectionString(InfrastructureServiceCollectionExtensions.ConnectionStringName)))
        {
            return;
        }

        throw new InvalidOperationException(
            $"The connection string '{ConnectionStringSetting}' is missing or empty. Set the environment variable '{ConnectionStringEnvironmentVariable}' before starting the API.");

